// The query is the whole input. A blank one is refused by name rather than searched
// for nothing, so an empty tool call is visible instead of reading as 'no results'.
const query = String($json.QUERY ?? '').trim();
if (!query) {
  throw new Error('QUERY is required: research needs something to search for');
}
return [{ json: { QUERY: query } }];

// One digest, so the writer reads one block of sources instead of two raw API
// payloads. Each source is read by node name: a failed HTTP node forwards its input
// unchanged, so the item itself cannot say which source answered.
const MAX_ITEMS = 5;
const MAX_TITLE = 120;
const cut = (value) => String(value || '').replace(/\s+/g, ' ').trim().slice(0, MAX_TITLE);

function readNode(name) {
  try {
    if (!$('' + name).isExecuted) return null;
    return $('' + name).first().json || null;
  } catch (error) {
    return null;
  }
}

const query = String((readNode('normalize_input') || {}).QUERY || '');
const hnRaw = readNode('search_hn');
const feedsRaw = readNode('search_feeds');
const hn = hnRaw && Array.isArray(hnRaw.hits) ? hnRaw.hits : null;
const feeds = feedsRaw && Array.isArray(feedsRaw.entries) ? feedsRaw.entries : null;

const lines = ['Query: ' + query];
const unavailable = [];

if (hn) {
  lines.push('Hacker News (' + Math.min(hn.length, MAX_ITEMS) + ' of ' + hn.length + '):');
  for (const hit of hn.slice(0, MAX_ITEMS)) {
    const url = hit.url || 'https://news.ycombinator.com/item?id=' + hit.objectID;
    lines.push('- ' + cut(hit.title) + ' | ' + url + ' | ' + (hit.points || 0) + ' points, ' + (hit.num_comments || 0) + ' comments');
  }
} else {
  unavailable.push('hacker news search');
}

if (feeds) {
  lines.push('Feeds (' + Math.min(feeds.length, MAX_ITEMS) + ' of ' + feeds.length + '):');
  for (const entry of feeds.slice(0, MAX_ITEMS)) {
    lines.push('- ' + cut(entry.title) + ' | ' + String(entry.url || '') + ' | ' + cut(((entry.feed || {}).title) || ''));
  }
} else {
  unavailable.push('feed search');
}

if (unavailable.length) {
  lines.push('Unavailable this run: ' + unavailable.join(', '));
}
if (!hn && !feeds) {
  lines.push('No source answered: write from the entry inputs alone and say the search failed.');
}

const found = (hn ? hn.length : 0) + (feeds ? feeds.length : 0);
return [{ json: { QUERY: query, RESULTS: found, DIGEST: lines.join('\n') } }];

